  var HTML_LANG = { ko: "ko", en: "en", "zh-CN": "zh-CN", "zh-TW": "zh-TW", ja: "ja", yue: "zh-HK", hi: "hi", th: "th", vi: "vi", ar: "ar", ind: "id", tur: "tr", si: "si", es: "es", fr: "fr" };
  var LOCALE = { ko: "ko-KR", en: "en-US", "zh-CN": "zh-CN", "zh-TW": "zh-TW", ja: "ja-JP", yue: "zh-HK", hi: "hi-IN", th: "th-TH", vi: "vi-VN", ar: "ar-SA", ind: "id-ID", tur: "tr-TR", si: "si-LK", es: "es-ES", fr: "fr-FR" };

  /* ---------------- 언어 감지 · 저장 ---------------- */

  function normalize(raw) {
    if (raw == null) return null;
    var s = String(raw).trim().toLowerCase();
    if (!s) return null;
    if (s === "ko" || s.indexOf("ko-") === 0 || s.indexOf("ko_") === 0) return "ko";
    if (s === "ja" || s.indexOf("ja-") === 0 || s.indexOf("ja_") === 0) return "ja";
    if (s === "hi" || s.indexOf("hi-") === 0 || s.indexOf("hi_") === 0) return "hi";
    if (s === "th" || s.indexOf("th-") === 0 || s.indexOf("th_") === 0) return "th";
    if (s === "vi" || s.indexOf("vi-") === 0 || s.indexOf("vi_") === 0) return "vi";
    if (s === "ar" || s.indexOf("ar-") === 0 || s.indexOf("ar_") === 0) return "ar";
    if (s === "tr" || s === "tur" || s.indexOf("tr-") === 0 || s.indexOf("tr_") === 0 || s.indexOf("tur-") === 0 || s.indexOf("tur_") === 0) return "tur";
    if (s === "si" || s.indexOf("si-") === 0 || s.indexOf("si_") === 0) return "si";
    if (s === "es" || s.indexOf("es-") === 0 || s.indexOf("es_") === 0) return "es";
    if (s === "fr" || s.indexOf("fr-") === 0 || s.indexOf("fr_") === 0) return "fr";
    if (s === "id" || s === "in" || s === "ind" || s.indexOf("id-") === 0 || s.indexOf("id_") === 0 || s.indexOf("in-") === 0 || s.indexOf("in_") === 0 || s.indexOf("ind-") === 0 || s.indexOf("ind_") === 0) return "ind";
    /* 광동어: 홍콩·마카오, 또는 yue 로 표기된 경우 */
    if (s === "yue" || s.indexOf("yue-") === 0 || s === "zh-hk" || s === "zh-mo") return "yue";
    if (
      s === "zh-tw" ||
      s === "zh-hant" ||
      s.indexOf("zh-hant") === 0 ||
      s.indexOf("zh-tw") === 0
    )
      return "zh-TW";
    if (s.indexOf("zh") === 0) return "zh-CN";
    if (s.indexOf("en") === 0) return "en";
    return null;
  }

  function stored() {
    try {
      var raw = window.localStorage.getItem(STORE_KEY);
      if (raw == null) return null;
      var val = raw;
      try {
        val = JSON.parse(raw);
      } catch (e) {
        /* 예전 값이 따옴표 없는 문자열이어도 받아들입니다 */
      }
      return normalize(val);
    } catch (e) {
      return null;
    }
  }

  function save(lang) {
    var picked = normalize(lang);
    if (!picked) return;
    try {
      window.localStorage.setItem(STORE_KEY, JSON.stringify(picked));
    } catch (e) {
      /* 저장 공간이 없으면 이번 방문에만 적용됩니다 */
    }
  }

  function fromBrowser() {
    var list = [];
    try {
      if (window.navigator.languages && window.navigator.languages.length) list = window.navigator.languages;
      else if (window.navigator.language) list = [window.navigator.language];
    } catch (e) {
      list = [];
    }
    for (var i = 0; i < list.length; i++) {
      var hit = normalize(list[i]);
      if (hit) return hit;
    }
    return null;
  }

  /* ?lang=ja 처럼 주소에 언어를 붙여 보내면 그 언어로 열립니다(공유 링크용) */
  function fromQuery() {
    try {
      var q = new URLSearchParams(location.search).get("lang");
      return q ? normalize(q) : null;
    } catch (e) {
      return null;
    }
  }

  function detect() {
    return fromQuery() || stored() || fromBrowser() || "ko";
  }

