    "pv.back": "กลับไปแอป",
    "pv.desc": "นโยบายความเป็นส่วนตัวสำหรับแอป Teakipedia ไม่มีการสมัครสมาชิก แต่โพสต์ชุมชน ใบสมัครลงรายชื่อร้านน้ำชา และรายการผลิตภัณฑ์ของผู้ผลิตจะถูกส่งแบบเข้ารหัสผ่าน HTTPS และเก็บไว้บนเซิร์ฟเวอร์ ส่วนโน้ตการชิมและการตั้งค่าแอปจะอยู่ในเบราว์เซอร์ของอุปกรณ์คุณ",
