    "pv.lead": "Teakipedia เป็นแอปที่มีคู่มือชา เครื่องจับเวลาชงชา โน้ตการชิม สารบบร้านน้ำชา และชุมชน แอปนี้<span class=\"key\">ไม่มีการสมัครหรือเข้าสู่ระบบ และการใช้แอปเพียงอย่างเดียวจะไม่เก็บข้อมูลส่วนบุคคลใด ๆ</span> เฉพาะสิ่งที่คุณเลือกส่ง — โพสต์ชุมชน ใบสมัครลงรายชื่อร้านน้ำชา รายการผลิตภัณฑ์ของผู้ผลิต — เท่านั้นที่จะถูกเข้ารหัสและเก็บบนเซิร์ฟเวอร์ของเรา ส่วนโน้ตการชิมและการตั้งค่าแอปจะอยู่บนอุปกรณ์ของคุณ",
