    "quiz.cardKicker": "රස පරීක්ෂණය",
    "quiz.cardSub": "ප්‍රශ්න 10ක් · විනාඩියක් · 301 අතරින් ඔබට ගැලපෙන තේ අපි සොයන්නෙමු",
    "quiz.cardTitle": "මට ගැලපෙන තේ මොකක්ද?",
