    "quiz.guide": "තේ මාර්ගෝපදේශයේ විවෘත කරන්න",
    "quiz.kicker": "ඔබේ කෝප්පය සොයන්න",
    "quiz.lead": "ප්‍රශ්න දහයකට පිළිතුරු දෙන්න, අපි තේ 301ක් අතරින් තෝරන්නෙමු — තේ පවුල් හය, එදිනෙදා සහ ඖෂධීය තේ, මිශ්‍රණ සහ සාම්ප්‍රදායික තේ.",
    "quiz.origin": "සම්භවය",
    "quiz.progress": "{n} / {total}",
    "quiz.q1": "ඔබ සාමාන්‍යයෙන් තේ බොන්නේ කවදාද, සහ ඇයි?",
    "quiz.q10": "අද මනෝභාවය සහ කන්නය?",
    "quiz.q10a": "මට සන්සුන් වී මනස පැහැදිලි කර ගැනීමට අවශ්‍යයි",
    "quiz.q10b": "මට ශක්තිය සහ අවධානය අවශ්‍යයි",
    "quiz.q10c": "මට සුවපහසු සහ සැනසිලිදායක දෙයක් අවශ්‍යයි",
    "quiz.q10d": "මට දීප්තිමත් සහ ප්‍රබෝධමත් දෙයක් අවශ්‍යයි",
    "quiz.q1a": "උදෑසන — අවදි වීමට සහ අවධානය යොමු කිරීමට",
    "quiz.q1b": "ආහාරයෙන් පසු, ප්‍රබෝධමත් වීමට",
    "quiz.q1c": "දහවල් — කෙටි විරාමයක්",
    "quiz.q1d": "රාත්‍රියේ, කැෆේන් ගැන කරදර නොවී",
    "quiz.q2": "ඔබව ආකර්ෂණය කරන සුවඳ කුමක්ද?",
    "quiz.q2a": "බැදපු, ඇට වර්ග වැනි රෝස්ට්",
    "quiz.q2b": "දීප්තිමත් මල් සුවඳ",
    "quiz.q2c": "ඉදුණු, පැණිරස පලතුරු",
    "quiz.q2d": "කොළ තණකොළ සහ නැවුම් බව",
    "quiz.q2e": "ගැඹුරු මෝල්ට් සහ වයස්ගත පැණිරස",
    "quiz.q2f": "සිට්‍රස් සහ ඖෂධ පැළෑටි",
    "quiz.q3": "ඝනත්වය සහ මුඛයේ හැඟීම?",
    "quiz.q3a": "ජලය මෙන් සැහැල්ලු සහ පැහැදිලි",
    "quiz.q3b": "මෘදු සහ සමබර",
    "quiz.q3c": "පොහොසත් සහ පූර්ණ",
    "quiz.q4": "ඔබ එය බීමට කැමති ආකාරය?",
    "quiz.q4a": "උණුසුම්, කෙළින්ම",
    "quiz.q4b": "අයිස් කළ හෝ සීතලෙන් පොඟවූ",
    "quiz.q4c": "කිරි සමඟ — කිරි තේ හෝ ලාටේ",
    "quiz.q5": "ඔබට ගැලපෙන කැෆේන් ප්‍රමාණය කොපමණද?",
    "quiz.q5a": "කැෆේන් හොඳයි — මම එම උත්තේජනයට කැමතියි",
    "quiz.q5b": "මධ්‍යස්ථ — දහවල් වන තෙක් ප්‍රමාණවත්",
    "quiz.q5c": "කරුණාකර ඩිකැෆ් හෝ කැෆේන් රහිත",
    "quiz.q6": "කුමන රසය ආකර්ෂණීයද?",
    "quiz.q6a": "පැණිරස, රසවත් උමාමි සහ වටකුරු අවසානයක්",
    "quiz.q6b": "පැහැදිලි, සැහැල්ලුවෙන් තිත්ත, කහට",
    "quiz.q6c": "ආකර්ෂණීය මිශ්‍ර තේ එකක් (masala, chai)",
    "quiz.q6d": "හුරුපුරුදු ධාන්‍ය සහ ඖෂධීය සටහන්",
    "quiz.q7": "දුම සහ රෝස්ට්?",
